elevated", "shape" to "large", "maxHeight" to "", "minHeight" to "", "vibrant" to false), "md-table-expand-toggle" to mapOf("buttonLabel" to "Expand row", "icon" to "chevron_right"), "md-table-foot" to mapOf("presentational" to false), "md-table-head" to emptyMap<String, Nothing>(), "md-table-pagination" to mapOf("count" to 0.0, "page" to 0.0, "rowsPerPage" to 10.0, "rowsPerPageOptions" to "5,10,25,50", "showFirstLast" to false, "labelDisplayedRows" to "%from%–%to% of %count%", "labelRowsPerPage" to "Rows per page:", "labelFirstPage" to "First page", "labelPreviousPage" to "Previous page", "labelNextPage" to "Next page", "labelLastPage" to "Last page", "labelAll" to "All", "compact" to false, "disabled" to false, "density" to 0.0), "md-table-row" to mapOf("rowgroup" to "body", "selected" to false, "disabled" to false, "selectable" to true, "clickable" to false, "value" to "", "expandable" to false, "expanded" to false, "highlight" to false), "md-table-sort-label" to mapOf("column" to "", "disabled" to false, "defaultOrder" to "asc", "iconPosition" to "end", "icon" to "", "inactiveIcon" to "always", "active" to false, "order" to "none", "sortedAscendingLabel" to "sorted ascending", "sortedDescendingLabel" to "sorted descending", "density" to 0.0), "md-table-toolbar" to mapOf("headline" to "", "supportingText" to "", "numSelected" to 0.0, "autoBind" to false, "labelSelected" to "%count% selected", "compact" to false, "density" to 0.0), "md-tabs" to mapOf("activeTabIndex" to 0.0, "variant" to "primary", "divider" to "full", "ariaLabelProp" to "", "tabWidth" to "equal", "width" to ""), "md-text-field" to mapOf("reserveSupportingSpace" to false, "variant" to "filled", "label" to "", "value" to "", "placeholder" to "", "type" to "text", "name" to "", "pattern" to "", "autocomplete" to "", "inputMode" to "", "enterKeyHint" to "", "autoCapitalize" to "", "spellcheck" to true, "disabled" to false, "readOnly" to false, "required" to false, "error" to false, "errorText" to "", "supportingText" to "", "prefixText" to "", "suffixText" to "", "clearable" to false, "passwordToggle" to false, "showPasswordLabel" to "Show password", "hidePasswordLabel" to "Hide password", "density" to 0.0, "multiline" to false, "speechToText" to false, "speechLang" to "", "restrict" to "", "formatOn" to "blur", "focusBorderWidth" to 3.0, "appearFocused" to false, "chipsWrap" to false, "debounce" to 0.0, "throttle" to 0.0, "inputRole" to "", "inputExpanded" to false, "inputAriaAutocomplete" to ""), "md-time-picker" to mapOf("variant" to "input", "format" to "12h", "value" to "", "name" to "", "min" to "", "max" to "", "required" to false, "label" to "Select time", "supportingText" to "", "error" to false, "errorText" to "", "reserveSupportingSpace" to false, "headline" to "", "headlineInputLabel" to "Enter time", "headlineDialLabel" to "Select time", "valueMissingLabel" to "Please select a time.", "rangeUnderflowLabel" to "Please select a time at or after {min}.", "rangeOverflowLabel" to "Please select a time at or before {max}.", "rangeOutsideLabel" to "Please select a time at or after {min} or at or before {max}.", "disabled" to false, "open" to false, "minuteStep" to 1.0, "cancelLabel" to "Cancel", "okLabel" to "OK", "hideTrigger" to false, "amLabel" to "AM", "pmLabel" to "PM", "hourLabel" to "Hour", "minuteLabel" to "Minute", "toggleDialLabel" to "Toggle dial picker", "toggleInputLabel" to "Toggle keyboard input", "periodLabel" to "Period", "periodLayout" to "vertical", "orientation" to "vertical", "responsive" to false, "density" to 0.0), "md-toolbar" to mapOf("variant" to "docked", "color" to "standard", "layout" to "horizontal", "alignment" to "start", "containerSemantics" to "toolbar", "ariaLabelProp" to "", "ariaLabelledby" to "", "density" to 0.0), "md-tooltip" to mapOf("text" to "", "subhead" to "", "variant" to "plain", "position" to "top", "autoPosition" to true, "offset" to 8.0, "crossOffset" to 0.0, "open" to false, "showDelay" to 500.0, "hideDelay" to 200.0, "disabled" to false, "density" to 0.0), "md-transfer-list" to mapOf("items" to emptyList<Nothing>(), "value" to emptyList<Nothing>(), "sourceTitle" to "Choices", "targetTitle" to "Chosen", "searchable" to true, "sourceSearchPlaceholder" to "Search choices", "targetSearchPlaceholder" to "Search chosen", "showSelectAll" to true, "searchIcon" to "search", "moveRightIcon" to "chevron_right", "moveLeftIcon" to "chevron_left", "moveAllRightIcon" to "keyboard_double_arrow_right", "moveAllLeftIcon" to "keyboard_double_arrow_left", "emptyIcon" to "", "emptyText" to "No items", "countTemplate" to "{checked}/{total} selected", "density" to 0.0, "disabled" to false, "singleStepOnly" to false, "moveRightLabel" to "Move selected to target", "moveLeftLabel" to "Move selected to source", "moveAllRightLabel" to "Move all to target", "moveAllLeftLabel" to "Move all to source"))
    val summaries: Map<String, String> = mapOf("md-accordion" to "Progressive disclosure for a set of sections. Groups md-accordion-item children, coordinates which are expanded, wires their heading level and panel roles, and adds optional drag/keyboard reordering plus a draggable floating panel mode.", "md-accordion-item" to "One collapsible section: a header button and the panel it controls. The header carries a headline, optional supporting text and leading/trailing icons; the panel holds your slotted content and is inert while collapsed.", "md-app-bar" to "The screen's header. Title, a leading navigation affordance, and trailing actions — in small / medium / large heights, plus a dedicated search variant for apps where search is the primary global function.", "md-area-chart" to "A trend with cumulative volume. A line chart with the region under the curve filled — stacked by default, so composition over time is the natural reading. Also does streamgraphs and low/high range bands.", "md-autocomplete" to "Type to filter, then choose. A text field with a suggestion listbox: single or multiple selection, optional free-text values, custom filtering, async loading, and virtualization for large option sets.", "md-avatar" to "A person or entity, as an image, initials, or a fallback glyph. It resolves one source from a fixed chain — image, then initials, then slotted content, then a person icon — with a deterministic container colour hashed from the identity.", "md-badge" to "A small count or marker attached to another element. A dot, or a count pill. variant=\"small\" is a bare dot for \"something is here\"; variant=\"large\" is a pill carrying a number or a glyph. It positions itself absolutely at the upper-right corner of the nearest positioned ancestor — a physical anchor (top: 0; right: 0), which does not mirror in RTL — and never takes pointer events.", "md-bar-chart" to "Compare values across categories. Vertical or horizontal bars, grouped or stacked, with legend, tooltips, zoom, drill-down, a polar (radial) mode and an expressive entrance animation.", "md-bottom-sheet" to "Supplementary content anchored to the bottom of the screen. Slides up over the page with a drag handle, an optional headline and close button, and an optional actions row. Both variants are modal: they render a scrim, trap focus, lock body scroll and close on Escape.", "md-breadcrumb-item" to "One crumb in the trail. A link to an ancestor, or the non-interactive current page, plus the separator that precedes it.", "md-breadcrumbs" to "Where the user is in a hierarchy, and the way back up. Wraps a trail of md-breadcrumb-item children in a labelled navigation region, keeps their position data in sync, and can collapse the middle of a long trail behind an overflow control.", "md-button" to "A discrete, committed action. Five emphasis levels, five sizes, round/square shape with M3-Expressive shape morphing, optional toggle mode, and native form participation (submit/reset) via ElementInternals.", "md-button-group" to "A set of related buttons that behave as one control. Wraps md-button / md-icon-button children, forces them into toggle mode, and manages selection, roving tabindex, arrow-key navigation, and — in connected mode — the fused container shape.", "md-card" to "A container for related content and actions about a single subject. Three variants (elevated, filled, outlined), an optional interactive mode with ripple and state layers, and an optional pointer-drag gesture that reports movement but never reorders anything itself.", "md-checkbox" to "Select none, one, or many from a related set. Tri-state (checked / unchecked / indeterminate), form-associated via ElementInternals, with the full constraint-validation API and its own supporting/error line.", "md-chip" to "A compact, contextual option — always part of a set. Four semantic variants (assist / filter / input / suggestion) cross with three surface appearances (outlined / filled / elevated), plus theme colour roles, optional selection and optional removal.", "md-color-picker" to "Pick an arbitrary colour. A saturation/value plate with hue and optional alpha sliders, numeric fields in hex / RGB / HSL, and an optional preset swatch row. Renders inline or as a popover behind a trigger you supply.", "md-date-picker" to "Choose a date, by calendar or by typing. Modal, modal-input, or docked, with locale-aware formatting, min/max bounds, a custom disabled-date predicate, and full constraint validation.", "md-dialog" to "A modal that interrupts to get a decision. Basic or full-screen, with an optional icon and headline, a scrim, a focus trap that reaches into slotted shadow roots, body-scroll locking, and an actions row you normally slot yourself.", "md-divider" to "A thin rule that separates content. Full-bleed or inset, horizontal or vertical. The host always exposes role=\"separator\" with a matching aria-orientation; the painted hairline lives inside the shadow root, so a page-level { margin: 0 } reset cannot wipe its insets.", "md-fab" to "The single most prominent action on a screen. Floats above the UI in seven color mappings and three sizes, and morphs between an icon-only circle and an extended pill that carries a label.", "md-fab-menu" to "A FAB that fans out into 2–6 related actions. Anchors to an existing md-fab by id, morphs that FAB's icon to close while open, and manages the popup's ARIA wiring, roving focus, and dismissal.", "md-fab-menu-item" to "One action row inside a md-fab-menu. An icon, a label, and a pill container. The parent menu owns opening, roving focus, and dismissal.", "md-icon-button" to "A common action expressed as an icon alone. Four emphasis styles, five sizes, three container widths, round/square shape with shape morphing, and an optional toggle mode with a distinct selected glyph.", "md-line-chart" to "A trend over a continuous axis. One or many series, six curve types, multiple y-axes, mark lines, drag-zoom and a slider band, plus a built-in loading state.", "md-list" to "A vertical set of related rows. It owns the container role and selection. Roving focus, arrow-key and typeahead navigation, and optional drag-to-reorder are all coordinated here on behalf of its md-list-item children.", "md-list-item" to "One row of a list. Up to three text lines, a leading visual, trailing content. The leading visual is an icon, avatar, or image; an optional panel expands detail in place. Normally a direct child of md-list, which supplies selection, roving focus and reordering.", "md-loading-indicator" to "The M3 Expressive loading moment. A morphing-shape indicator for indeterminate waits — distinct from a progress indicator, which reports how far along something is.", "md-menu" to "A temporary set of actions or options, anchored to a trigger. Handles placement, viewport flipping and clamping, roving focus, typeahead and dismissal. It is also the dropdown surface inside md-select, md-multi-select, md-autocomplete and md-date-picker.", "md-menu-item" to "One row in a md-menu. A command, or a checkbox/radio option, with optional icons, supporting text, a badge and trailing text.", "md-menu-item-group" to "A labelled section within a md-menu. Groups related rows under a heading so a long menu stays scannable, and scopes radio exclusivity to the section.", "md-meter" to "A read-only graphical display of a numeric value within a known range. Storage used, quota consumed, password strength, battery level. role=\"meter\" with the full ARIA value contract on the host, value clamping, Intl-driven formatting (locale-aware percent by default), and MD3 semantic status colors.", "md-multi-select" to "Pick several values from a list. Everything md-select does, plus multiple selection shown as removable chips / a count / plain text, an optional select-all row, a selection cap, and a field, button or fully custom trigger.", "md-navigation-bar" to "Top-level destinations on a compact screen. A bottom bar of 3–5 destinations. Owns the active index and keyboard movement across its md-navigation-tab children.", "md-navigation-rail" to "Top-level destinations on a large screen. A rail that can expand to a labelled drawer, host a FAB and a logo, and optionally float modally — laid out vertically (the M3 default) or horizontally as a top-of-page application bar.", "md-navigation-rail-tab" to "One destination in a md-navigation-rail. Icon, label, active indicator, optional badge, a stable value for routing, and an optional dropdown.", "md-navigation-tab" to "One destination in a md-navigation-bar. Icon, label, active indicator, and an optional badge, with optional URL navigation on activation.", "md-number-field" to "A number, typed or stepped. An md-text-field with locale-aware Intl.NumberFormat display (currency, percent, units, grouping), arrow-key / stepper-button / wheel stepping, and native form participation with the raw numeric value.", "md-organization-chart" to "A tree of avatar cards joined by connectors. Renders a hierarchy — reporting lines, categories, taxonomies — with collapsible branches, optional selection and the full WAI-ARIA tree keyboard model.", "md-otp-field" to "One-time-code entry. Renders length real cells in its own shadow root (it owns the inputs, so every cell carries full ARIA), routes all entry — typing, paste, SMS autofill — through one sanitizing pipeline, and participates in forms via ElementInternals with the full constraint-validation API. No hidden input, no wrapper md-text-field.", "md-pie-chart" to "Parts of a single whole. Pie, donut (inner-radius), or nested rings, with a centre slot for a headline figure and drill-down support.", "md-progress-indicator" to "How far along an activity is. Linear or circular, determinate or indeterminate, with the M3 Expressive wave treatment and four-colour mode.", "md-radio" to "Exactly one option from a small, visible set. Radios sharing a name form an exclusive group with a roving tabstop and arrow-key navigation, and participate in form submission and validation.", "md-rating" to "A subjective score on a small, discrete scale. Star (or custom-glyph) rating with configurable maximum, optional half-steps, hover preview, and form participation via ElementInternals.", "md-ripple" to "The touch-feedback primitive. Paints the MD3 press ripple inside its positioned parent. Used internally by 24 components — you only reach for it directly when building a custom interactive surface.", "md-search" to "A search entry point with its own results surface. A bar (or icon trigger) that expands into a full-screen or docked panel, with slotted suggestions and results, optional voice input, and live-region announcements. It renders the surface and reports the query — it never fetches or filters anything itself.", "md-segmented-button" to "One segment inside a md-segmented-button-set. Carries a value, an optional icon, a label, and the selected checkmark. The parent set owns selection and stamps each segment with its position.", "md-segmented-button-set" to "A choice between 2–5 exclusive options, all visible at once. Wraps md-segmented-button children, owns the selection, and stamps each child with its position so the fused container renders correct end caps.", "md-select" to "Pick exactly one value from a list. A readonly md-text-field trigger with an md-menu listbox popup, optional in-menu filtering, async option loading and row virtualization for large lists. Form-associated with full constraint validation.", "md-select-option" to "A declarative data carrier for the pickers. It renders nothing visible (:host { display: none }). The parent picker reads its props and projects them into its own md-menu dropdown as real md-menu-item rows.", "md-side-sheet" to "Supplementary content along the side of the screen. Standard (an inline, non-modal region that sits beside your content) or modal (a fixed overlay with a scrim and a focus trap), anchored to either logical edge, with an optional back affordance for nested flows.", "md-skeleton" to "A content-shaped loading placeholder. Text lines, rectangles, rounded blocks, or circles, with pulse or wave animation — used to reserve layout while data loads.", "md-slider" to "Choose a value, or a range, along a continuum. Horizontal or vertical, single or two-thumb range, discrete steps with tick marks, value indicators, and an optional inset icon that travels with the handle.", "md-snackbar" to "Brief, low-priority feedback about something that just happened. Appears over the content, auto-hides after 4 seconds, and can carry a single action — canonically \"Undo\".", "md-sparkline" to "A micro-chart with no chrome. A trend line, bar, or area sized to sit inside a table cell, a card, or a line of text. No axes, no legend, no title.", "md-split-button" to "One default action plus a menu of variations. Two fused segments: a leading button that runs the default action, and a trailing toggle that opens a menu. The component renders the button — you supply and position the menu.", "md-status-dot" to "A presence or health indicator. A small coloured dot with six states and an optional pulse, absolutely positioned onto an avatar, a row, or any tile.", "md-step" to "One step inside an md-stepper. An indicator (number, dot, check, pencil or error glyph), a label, an optional supporting line, and — where the layout calls for it — the step's own content panel.", "md-stepper" to "A sequential process broken into ordered steps. Owns the active index, the built-in navigation and whether the user may jump ahead, and pushes layout plus every localized word down to its slotted md-step children.", "md-sub-menu-item" to "A menu row that opens a nested submenu. Same anatomy as md-menu-item, plus a submenu slot that you fill with a second md-menu.", "md-switch" to "An immediate on/off setting. Track-and-handle toggle with optional state icons, form-associated via ElementInternals, and a cancelable before-change event for controlled usage.", "md-tab" to "One tab in a md-tabs strip. A label and/or icon, an optional badge, and the active indicator that md-tabs glides between tabs.", "md-tab-panel" to "The content of one tab. A single active flag decides whether it is shown; everything else is your content, projected through the default slot.", "md-tab-panels" to "The content container that pairs with a md-tabs strip. It finds the strip, follows its mdTabChange, drives active / inert on its md-tab-panel children, and wires the tab↔panel ARIA in both directions.", "md-table" to "The composable table primitive. You author every row; the table owns the CSS-Grid layout, sticky and frozen headers, column pinning and visibility, sort and selection state, striping, expressive reorder motion, and the loading and empty states.", "md-table-body" to "The data rowgroup — for md-table. A marker element that groups the data rows. md-table reads it to decide which rows are body rows (striping, selection and hover apply only to them), and it is the group the built-in FLIP motion animates. It has no author-settable props and no box of its own.", "md-table-cell" to "One cell of an md-table. Renders as a data cell, a column header or a row header depending on head and scope, with alignment, spanning, sticky pinning and truncation options. It is a dumb surface: row state (selected, disabled, header) arrives as inherited CSS custom properties cast by md-table-row.", "md-table-container" to "The surface around a md-table. It supplies elevation, shape and the scroll region, plus the top / bottom bands where a toolbar and pagination sit outside the scroll. It also brackets pagination changes with the table's built-in motion.", "md-table-expand-toggle" to "The chevron that expands a table row. A stateless wrapper around an md-icon-button that finds its owning md-table-row, toggles it on click, and rotates with the row's expanded state.", "md-table-foot" to "The summary rowgroup — for md-table. A marker element that groups totals and aggregate rows. md-table reads it to give those rows the footer surface and its own top divider, and to keep them out of the selection model. It has no author-settable props and no box of its own.", "md-table-head" to "The column-header rowgroup — for md-table. A marker element that groups the header row(s). md-table reads it to decide which rows are header rows, and in frozen-header mode projects it into the separate header grid. It has no props and no box of its own.", "md-table-pagination" to "The page controls under a table. A \"1–10 of 120\" readout, a rows-per-page selector and previous/next (optionally first/last) navigation. It reports intent through events — it never slices your data.", "md-table-row" to "One row of a md-table. A real grid box that spans the table's tracks and lays its md-table-cell children onto them with grid-template-columns: subgrid, so hover, stripes, dividers, selection tint, sticky rows and focus rings all paint on the row itself.", "md-table-sort-label" to "The sortable-column affordance. Goes inside a header cell, shows the current sort direction, and emits a request to sort — the parent md-table turns that request into sort state and hands it back.", "md-table-toolbar" to "The band above a table. Title and supporting text in the resting state; a selection count and bulk actions once rows are selected. It is a presentation band with two modes — it never selects anything itself.", "md-tabs" to "Switch between sibling views within one screen. The tab strip owns the active index, roving focus, the child tabs' variant, and the sliding indicator. It renders no content of its own — pair it with md-tab-panels.", "md-text-field" to "The library's single text-entry primitive. Filled and outlined variants, single-line or multiline, with optional clear / password-toggle / speech-to-text affordances, display masking via formatter/parser, a debounced/throttled search event, and the full constraint-validation API through ElementInternals.", "md-time-picker" to "Choose a time, by dial or by typing. 12h/24h formats, min/max bounds with templated validation messages, overnight ranges, and full constraint validation.", "md-toolbar" to "A persistent cluster of local actions. Docked or floating, horizontal or vertical, with an optional FAB slot. Where a menu is temporary, a toolbar keeps the essential actions on screen — and it wires the WAI-ARIA toolbar keyboard pattern over whatever controls you slot in.", "md-tooltip" to "A short explanation of a UI element, shown on hover or focus. Plain tooltips label icon-only controls; rich tooltips add a subhead, body text and actions. You wrap the trigger in the default slot and the component positions, flips and clamps the popup for you.", "md-transfer-list" to "A dual-list selector. Two columns — source and target — with per-side search, select-all headers, checkbox rows, and four movers between them. The value prop is the set of item values currently in the target column.")
}
